import React, { useMemo } from 'react';

import {
  _isEmptyStateActions,
  type EmptyStateActionsProps,
} from '../slot-components/Actions.js';
import {
  _isEmptyStateDetails,
  type EmptyStateDetailsProps,
} from '../slot-components/Details.js';
import {
  _isEmptyStateFooter,
  type EmptyStateFooterProps,
} from '../slot-components/Footer.js';
import {
  _isEmptyStateTitle,
  type EmptyStateTitleProps,
} from '../slot-components/Title.js';
import {
  _isEmptyStateVisual,
  type EmptyStateVisualProps,
} from '../slot-components/Visual.js';
import {
  _isEmptyStateVisualPreset,
  EmptyStateVisualPresetProps,
} from '../slot-components/VisualPreset.js';

/** @internal */
type EmptyStateSlots = {
  Actions: React.ReactElement<EmptyStateActionsProps> | null;
  Details: React.ReactElement<EmptyStateDetailsProps> | null;
  Footer: React.ReactElement<EmptyStateFooterProps> | null;
  Title: React.ReactElement<EmptyStateTitleProps> | null;
  Visual: React.ReactElement<EmptyStateVisualProps> | null;
  VisualPreset: React.ReactElement<EmptyStateVisualPresetProps> | null;
};

/**
 * Helper hook that will extract the Slots used in the empty state component and collect the data / components.
 *
 * @internal
 */
export function _useEmptyStateSlots(
  children: React.ReactNode,
): EmptyStateSlots {
  return useMemo(() => {
    const slots: EmptyStateSlots = {
      Actions: null,
      Details: null,
      Footer: null,
      Title: null,
      Visual: null,
      VisualPreset: null,
    };

    React.Children.forEach(children, (child) => {
      if (_isEmptyStateActions(child)) {
        slots.Actions = child;
      } else if (_isEmptyStateDetails(child)) {
        slots.Details = child;
      } else if (_isEmptyStateFooter(child)) {
        slots.Footer = child;
      } else if (_isEmptyStateTitle(child)) {
        slots.Title = child;
      } else if (_isEmptyStateVisual(child)) {
        slots.Visual = child;
      } else if (_isEmptyStateVisualPreset(child)) {
        slots.VisualPreset = child;
      } else if (child !== null) {
        // eslint-disable-next-line no-console
        console.warn(
          'The used child is not supported by EmptyState. Only Actions, Content, Details, Title, Visual, and VisualPreset are valid children of EmptyState.',
        );
      }
    });

    return slots;
  }, [children]);
}
